import { test, expect } from '@playwright/test';

test.describe('Search Filter Results', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display the correct number of results for the first filter option', async ({ page }) => {
    await page.getByRole('button', { name: 'Filter Option 1' }).click();
    const resultsCount = await page.getByText(/results found/i).innerText();
    expect(resultsCount).toBe('10 results found'); // Replace with the expected count
  });

  test('should display the correct number of results for the second filter option', async ({ page }) => {
    await page.getByRole('button', { name: 'Filter Option 2' }).click();
    const resultsCount = await page.getByText(/results found/i).innerText();
    expect(resultsCount).toBe('5 results found'); // Replace with the expected count
  });
});
